INSERT INTO services (slug, title, short_title, category_id, icon_key, image_media_id, summary, description, sort_order) VALUES ('home-nursing-care', 'Home Nursing Care', '', (SELECT id FROM service_categories WHERE slug = 'medical'), 'stethoscope', (SELECT id FROM media WHERE file_name = 'home-nursing.jpg'), 'Professional nursing assistance at home, from wound dressing and injections to post-operative support and routine health monitoring.', 'Our home nursing service brings qualified nursing assistance to your doorstep, so patients can receive attentive clinical support in familiar surroundings. Nurses follow the instructions of the treating doctor and keep the family informed at every step.', 1);
