INSERT INTO services (slug, title, short_title, category_id, icon_key, image_media_id, summary, description, sort_order) VALUES ('elderly-care', 'Elderly Care', '', (SELECT id FROM service_categories WHERE slug = 'caregivers'), 'heartHandshake', (SELECT id FROM media WHERE file_name = 'elderly-care.jpg'), 'Respectful, patient assistance for senior citizens with daily routines, mobility, hygiene and warm companionship.', 'Growing older at home should feel safe and dignified. Our elderly caregivers help seniors with everyday routines, offer steady support when moving around, and provide the kind of companionship that keeps the day pleasant and engaged.', 2);
