INSERT INTO services (slug, title, short_title, category_id, icon_key, image_media_id, summary, description, sort_order) VALUES ('patient-care-at-home', 'Patient Care at Home', '', (SELECT id FROM service_categories WHERE slug = 'medical'), 'bed', (SELECT id FROM media WHERE file_name = 'patient-care.jpg'), 'Hands-on help for bedridden and recovering patients, including feeding, bathing, mobility and day-to-day care coordination.', 'Caring for a bedridden or recovering patient is demanding. Our patient care assistants take on the hands-on daily tasks, from feeding and bathing to safe repositioning, while coordinating the routine with your family.', 3);
