INSERT INTO services (slug, title, short_title, category_id, icon_key, image_media_id, summary, description, sort_order) VALUES ('full-time-caregiver', 'Full-Time Caregiver', '', (SELECT id FROM service_categories WHERE slug = 'caregivers'), 'userCheck', (SELECT id FROM media WHERE file_name = 'full-time-caregiver.jpg'), 'A dedicated caregiver at home for day and night assistance, with care shaped around the patient’s routine.', 'When someone needs consistent support through the day, or around the clock, a full-time caregiver provides continuity. The same familiar caregiver learns the patient’s preferences and routine, offering steady, personalised help.', 4);
