INSERT INTO services (slug, title, short_title, category_id, icon_key, image_media_id, summary, description, sort_order) VALUES ('icu-at-home', 'ICU at Home', '', (SELECT id FROM service_categories WHERE slug = 'medical'), 'monitorDot', (SELECT id FROM media WHERE file_name = 'icu-at-home.jpg'), 'Critical care set up at home, with medical equipment, trained nursing staff and continuous monitoring, as advised by the treating doctor.', 'For patients who need intensive, round-the-clock medical attention, we help set up ICU-level care in the comfort of home. Equipment and care are arranged according to the treating doctor’s advice, with trained nursing staff monitoring the patient and keeping the doctor and family updated.', 11);
