INSERT INTO faq_categories (slug, label, sort_order) VALUES ('support', 'Support', 3);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'services'), 'What services does Advanced Home Care provide?', 'We provide home nursing care, elderly care, patient care at home, full-time and part-time caregivers, medicine management, food preparation and meal assistance, post-surgery care, bedside attendants, personal care assistance and ICU at home. You can explore each service on our Services page.', 1);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'services'), 'Can I arrange a nurse for home care?', 'Yes. Our home nursing service covers professional nursing assistance such as wound dressing, injections, post-operative support and health monitoring, following the instructions of the patient’s treating doctor. Share your requirements with us and we will discuss what is suitable.', 2);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'services'), 'Do you provide full-time and part-time caregivers?', 'Yes. Full-time caregivers offer dedicated day and/or night assistance, while part-time caregivers visit on a schedule that suits your family. We help you decide which option fits the patient’s needs.', 3);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'services'), 'Can I arrange care for elderly family members?', 'Absolutely. Our elderly care service supports seniors with daily routines, mobility, personal hygiene and companionship, so they can stay comfortable and safe at home.', 4);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'services'), 'Do you provide post-surgery assistance?', 'Yes. Post-surgery care includes recovery assistance, mobility support, personal hygiene and daily care, with coordination alongside the treating medical team’s instructions.', 5);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'services'), 'Can caregivers help with daily meals?', 'Yes. Our Food Preparation & Meal Assistance service includes daily meal preparation in line with patient-specific dietary instructions, as well as feeding assistance when needed.', 6);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'booking'), 'Can I request a specific care duration?', 'Yes. You can request short-term or long-term care, daytime or night-time assistance, or 12-hour and 24-hour care. Mention your preferred duration in the enquiry form and our team will discuss availability with you.', 7);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'booking'), 'How can I book a home care service?', 'Fill in the Book Home Care enquiry form with the patient’s details, the service you need, your preferred duration and start date. Our team reviews your enquiry and contacts you to discuss the requirements before anything is confirmed.', 8);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'booking'), 'How is the caregiver assigned?', 'After understanding the patient’s condition and your requirements, our team identifies a suitable care professional. A caregiver is assigned only after the service details are confirmed with you and availability has been checked.', 9);
INSERT INTO faqs (category_id, question, answer, sort_order) VALUES ((SELECT id FROM faq_categories WHERE slug = 'support'), 'How can I contact your support team?', 'You can reach us through the enquiry form on our Contact page. Our phone, WhatsApp and email details are listed on the Contact page as well.', 10);
