INSERT INTO legal_pages (slug, title, intro) VALUES ('privacy-policy', 'Privacy Policy', 'This Privacy Policy explains how Advanced Home Care collects, uses and protects the personal information you share with us through this website.');
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'privacy-policy'), 'Information We Collect', 'When you submit an enquiry or booking request, we may collect your name, mobile number, email address, city and address, as well as patient details such as name, age, the service required, preferred care duration, start date and any additional requirements you choose to share.
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'privacy-policy'), 'How We Use Your Information', 'We use the information you provide to respond to your enquiry, understand care requirements, discuss suitable services, and coordinate care if you choose to proceed.
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'privacy-policy'), 'Health-Related Information', 'Details about a patient’s condition are sensitive. Please share only what is needed for us to understand the care required. We handle such information with care and limit access to people who need it to respond to your enquiry or provide services.', 3);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'privacy-policy'), 'Sharing of Information', 'We may share relevant information with the care professional assigned to a patient, and where required by law. We may use trusted service providers (for example, hosting or communication tools) who process data on our behalf under appropriate safeguards.', 4);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'privacy-policy'), 'Data Retention & Security', 'We keep personal information only for as long as necessary for the purposes described above or as required by law, and we take reasonable measures to protect it from unauthorised access.', 5);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'privacy-policy'), 'Your Choices', 'You may contact us to access, correct or request deletion of the personal information you have shared with us, subject to applicable legal requirements.', 6);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'privacy-policy'), 'Contact Us', 'For any privacy-related questions, please reach us through the details on our Contact page.', 7);
INSERT INTO legal_pages (slug, title, intro) VALUES ('terms', 'Terms & Conditions', 'These Terms & Conditions govern your use of the Advanced Home Care website and the enquiry process. By using this website, you agree to these terms.');
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'terms'), 'Use of This Website', 'This website provides general information about our home care services. Content is for informational purposes only and is not a substitute for professional medical advice, diagnosis or treatment.', 1);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'terms'), 'Enquiries Are Not Confirmed Bookings', 'Submitting an enquiry or booking request through this website does not confirm a service or the assignment of a caregiver. Services are confirmed only after our team has discussed your requirements with you and checked availability.', 2);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'terms'), 'Accuracy of Information', 'You agree to provide accurate and complete information in any enquiry, including relevant details about the patient’s condition, so that we can recommend suitable care.', 3);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'terms'), 'Medical Responsibility', 'Our care professionals follow instructions from the patient’s treating doctor where applicable. Medical decisions, diagnosis and prescriptions remain the responsibility of the treating medical team. In an emergency, contact your local emergency services immediately.', 4);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'terms'), 'Service Terms, Fees & Cancellations', 'Service scope, schedules, fees, payment terms and cancellation policies are agreed separately with you before services begin.', 5);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'terms'), 'Intellectual Property', 'The Advanced Home Care name, logo and website content are the property of Advanced Home Care and may not be used without permission.', 6);
INSERT INTO legal_sections (page_id, heading, body, sort_order) VALUES ((SELECT id FROM legal_pages WHERE slug = 'terms'), 'Changes to These Terms', 'We may update these terms from time to time. Changes take effect when published on this page.', 7);
